#include "MeshCapture.h"
#include <d3dcompiler.h>
#include <array>
#include <cstdio>
#include <cstdlib>
using Microsoft::WRL::ComPtr;
static unsigned checks{};
static void require(bool value,const char* message){++checks;if(!value){fprintf(stderr,"FAIL: %s\n",message);exit(1);}}
static std::vector<char> read(const std::filesystem::path& path){std::ifstream stream(path,std::ios::binary);return {std::istreambuf_iterator<char>(stream),{}};}
int wmain(int argc,wchar_t** argv){
 require(argc==2,"output directory");std::filesystem::path directory=argv[1];std::filesystem::create_directories(directory);
 ComPtr<ID3D11Device> device;ComPtr<ID3D11DeviceContext> context;require(SUCCEEDED(D3D11CreateDevice(nullptr,D3D_DRIVER_TYPE_HARDWARE,nullptr,0,nullptr,0,D3D11_SDK_VERSION,&device,nullptr,&context)),"hardware D3D11 device");
 const char* source="float4 main(float4 p:POSITION,uint4 i:BLENDINDICES,float4 w:BLENDWEIGHT):SV_Position{return p+float4(i)*w;}";ComPtr<ID3DBlob> shader;require(SUCCEEDED(D3DCompile(source,strlen(source),nullptr,nullptr,nullptr,"main","vs_5_0",0,0,&shader,nullptr)),"mesh input signature");
 D3D11_INPUT_ELEMENT_DESC elements[]={{"POSITION",0,DXGI_FORMAT_R32G32B32A32_FLOAT,0,0,D3D11_INPUT_PER_VERTEX_DATA,0},{"BLENDINDICES",0,DXGI_FORMAT_R8G8B8A8_UINT,0,16,D3D11_INPUT_PER_VERTEX_DATA,0},{"BLENDWEIGHT",0,DXGI_FORMAT_R32G32B32A32_FLOAT,0,20,D3D11_INPUT_PER_VERTEX_DATA,0}};
 ComPtr<ID3D11InputLayout> layout;require(SUCCEEDED(device->CreateInputLayout(elements,3,shader->GetBufferPointer(),shader->GetBufferSize(),&layout)),"native input layout");MeshCapture::RememberLayout(layout.Get(),elements,3);context->IASetInputLayout(layout.Get());context->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
 auto make=[&](UINT bytes,UINT bind,UINT misc=0,UINT stride=0){std::vector<char> data(bytes);for(UINT i=0;i<bytes;++i)data[i]=char((i*17+11)%256);D3D11_BUFFER_DESC desc{};desc.ByteWidth=bytes;desc.Usage=D3D11_USAGE_DEFAULT;desc.BindFlags=bind;desc.MiscFlags=misc;desc.StructureByteStride=stride;D3D11_SUBRESOURCE_DATA initial{data.data(),0,0};ComPtr<ID3D11Buffer> buffer;require(SUCCEEDED(device->CreateBuffer(&desc,&initial,&buffer)),"native mesh resource");return std::make_pair(buffer,data);};
 auto vb=make(360,D3D11_BIND_VERTEX_BUFFER),ib=make(48,D3D11_BIND_INDEX_BUFFER),bones=make(288,D3D11_BIND_SHADER_RESOURCE,D3D11_RESOURCE_MISC_BUFFER_STRUCTURED,144);
 auto* vertices=vb.first.Get();UINT stride=36,offset=36;context->IASetVertexBuffers(0,1,&vertices,&stride,&offset);context->IASetIndexBuffer(ib.first.Get(),DXGI_FORMAT_R16_UINT,4);
 D3D11_SHADER_RESOURCE_VIEW_DESC desc{};desc.ViewDimension=D3D11_SRV_DIMENSION_BUFFER;desc.Buffer.FirstElement=1;desc.Buffer.NumElements=1;ComPtr<ID3D11ShaderResourceView> view;require(SUCCEEDED(device->CreateShaderResourceView(bones.first.Get(),&desc,&view)),"bone buffer view with nonzero first element");auto* srv=view.Get();context->VSSetShaderResources(1,1,&srv);
 uint64_t copied{};MeshCapture::Data data;MeshCapture::Capture(context.Get(),true,7,-2,3,1,copied,data);
 require(copied==696 && data.buffers.size()==3,"bounded VB/IB/bone asynchronous copies");require(data.indexed && data.start==7 && data.base==-2 && data.instances==3 && data.firstInstance==1,"exact indexed and instanced arguments");require(data.layout.find("BLENDINDICES")!=std::string::npos && data.layout.find("\"offset\":20")!=std::string::npos,"complete semantic and format layout");
 ComPtr<ID3D11Buffer> unchanged;UINT currentStride{},currentOffset{};context->IAGetVertexBuffers(0,1,&unchanged,&currentStride,&currentOffset);require(unchanged.Get()==vb.first.Get() && currentStride==36 && currentOffset==36,"native vertex binding unchanged");DXGI_FORMAT format{};context->IAGetIndexBuffer(&unchanged,&format,&currentOffset);require(unchanged.Get()==ib.first.Get() && format==DXGI_FORMAT_R16_UINT && currentOffset==4,"native index binding unchanged");ComPtr<ID3D11ShaderResourceView> unchangedView;context->VSGetShaderResources(1,1,&unchangedView);require(unchangedView.Get()==view.Get(),"native bone binding unchanged");ComPtr<ID3D11InputLayout> unchangedLayout;context->IAGetInputLayout(&unchangedLayout);require(unchangedLayout.Get()==layout.Get(),"native input layout unchanged");
 D3D11_QUERY_DESC qd{D3D11_QUERY_EVENT,0};ComPtr<ID3D11Query> query;require(SUCCEEDED(device->CreateQuery(&qd,&query)),"completion event");context->End(query.Get());context->Flush();HRESULT hr=S_FALSE;for(unsigned attempt=0;attempt<500 && hr==S_FALSE;++attempt){hr=context->GetData(query.Get(),nullptr,0,0);if(hr==S_FALSE)Sleep(1);}require(hr==S_OK,"bounded GPU completion");
 auto json=MeshCapture::Write(context.Get(),directory,"fixture",data);require(read(directory/"fixture-mesh-vertex0.bin")==vb.second,"captured vertices byte identical");require(read(directory/"fixture-mesh-index0.bin")==ib.second,"captured indices byte identical");require(read(directory/"fixture-mesh-bones1.bin")==bones.second,"captured bones byte identical");require(json.find("\"base\":-2")!=std::string::npos && json.find("\"stride\":144,\"offset\":1")!=std::string::npos,"persisted draw and bone-view offset");
 uint64_t full=64*1024*1024;MeshCapture::Data denied;MeshCapture::Capture(context.Get(),true,0,0,1,0,full,denied);require(denied.buffers.empty() && full==64*1024*1024,"global capture budget enforced");require(SUCCEEDED(device->GetDeviceRemovedReason()),"device healthy");printf("PASS: %u mesh capture GPU checks; exact mesh bytes, draw arguments, layout, offsets, budget and native binding preservation.\n",checks);
}
